import itertools

def is_colorful(m, n, w):
    for flavors in itertools.product(range(n), repeat=m):
        is_colorful_seq = True
        for i in range(m):
            window = [flavors[(i + j) % m] for j in range(w)]
            if len(set(window)) < n:
                is_colorful_seq = False
                break
        if is_colorful_seq:
            return True
    return False

