def find_f(q, w):
    # f(q) is the set of possible sums d1 + ... + dq
    # such that d_i + d_{i+1} >= w and d_i <= w-1.
    # This is a DP.
    # dp[q][d] is True if there's a sum of q d_i's ending in d.
    dp = [[False] * w for _ in range(q + 1)]
    for d in range(1, w):
        dp[1][d] = True

    for i in range(1, q):
        for d_prev in range(1, w):
            if dp[i][d_prev]:
                for d_curr in range(1, w):
                    if d_prev + d_curr >= w:
                        dp[i+1][d_curr] = True

    sums = set()
    for d in range(1, w):
        if dp[q][d]:
            # This is not enough, we need the sums.
            pass

    # Let's re-do the DP to keep track of the sums.
    # dp[i][d] = set of possible sums of i d_i's ending in d.
    dp = [[set() for _ in range(w)] for _ in range(q + 1)]
    for d in range(1, w):
        dp[1][d].add(d)

    for i in range(1, q):
        for d_prev in range(1, w):
            for s in dp[i][d_prev]:
                for d_curr in range(1, w):
                    if d_prev + d_curr >= w:
                        dp[i+1][d_curr].add(s + d_curr)

    all_sums = set()
    for d in range(1, w):
        all_sums.update(dp[q][d])
    return sorted(list(all_sums))

