def find_f(q, w):
    # dp[i][d] = set of possible sums of i d_k's ending in d.
    # Condition: d_k + d_{k+1} >= w, d_k <= w-1.
    dp = [[set() for _ in range(w)] for _ in range(q + 1)]
    for d in range(1, w):
        dp[1][d].add(d)

    for i in range(1, q):
        for d_prev in range(1, w):
            for s in dp[i][d_prev]:
                for d_curr in range(1, w):
                    if d_prev + d_curr >= w:
                        dp[i+1][d_curr].add(s + d_curr)

    all_sums = set()
    for d in range(1, w):
        all_sums.update(dp[q][d])
    return sorted(list(all_sums))

