def find_f_fast(q, w):
    # dp[i][d] is the set of possible sums of i d_k's ending in d.
    # Let's just track the min and max sum for each i and d.
    # min_sum[i][d] = min sum of i d_k's ending in d.
    # max_sum[i][d] = max sum of i d_k's ending in d.
    # Since the set of sums is always a contiguous range (we'll check this),
    # we only need min and max.

    min_sum = [[float('inf')] * w for _ in range(q + 1)]
    max_sum = [[float('-inf')] * w for _ in range(q + 1)]

    for d in range(1, w):
        min_sum[1][d] = d
        max_sum[1][d] = d

    for i in range(1, q):
        for d_prev in range(1, w):
            if min_sum[i][d_prev] != float('inf'):
                for d_curr in range(max(1, w - d_prev), w):
                    min_sum[i+1][d_curr] = min(min_sum[i+1][d_curr], min_sum[i][d_prev] + d_curr)
                    max_sum[i+1][d_curr] = max(max_sum[i+1][d_curr], max_sum[i][d_prev] + d_curr)

    all_sums = set()
    for d in range(1, w):
        if min_sum[q][d] != float('inf'):
            # If the sums are contiguous, we can just add the range.
            # Let's assume they are contiguous for now and check later.
            for s in range(min_sum[q][d], max_sum[q][d] + 1):
                all_sums.add(s)
    return all_sums

